CREATE OR REPLACE FUNCTION public.apiosk_apis_review_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'gateway_v2', 'kyb', 'providers', 'catalog', 'actions', 'billing', 'agents', 'wallets', 'research', 'integrations', 'observability', 'support', 'content', 'operations', 'identity', 'extensions'
AS $function$
declare
  v_status_changed boolean;
  v_approved_api_id text;
begin
  v_status_changed := tg_op = 'INSERT';
  if tg_op = 'UPDATE' then
    v_status_changed := old.status is distinct from new.status;
  end if;

  -- The approval RPC sets this transaction-local value for exactly one API.
  -- All ordinary portal, MCP, service-role and admin writes see NULL/empty.
  v_approved_api_id := nullif(
    current_setting('apiosk.api_review_approved_id', true),
    ''
  );

  if new.status = 'active'
     and v_status_changed
     and v_approved_api_id is distinct from new.id::text
  then
    new.status := 'pending';
  end if;

  -- A fresh submission or resubmission starts a new review clock and cannot
  -- retain the identity of an earlier reviewer.
  if new.status = 'pending'
     and v_status_changed
  then
    new.submitted_for_review_at := now();
    new.reviewed_by := null;
  end if;

  -- This branch is reachable for a publish transition only through the
  -- API-specific approval capability above.
  if new.status = 'active' and new.approved_at is null then
    new.approved_at := now();
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.apiosk_auto_verify_owner_apis()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'gateway_v2', 'kyb', 'providers', 'catalog', 'actions', 'billing', 'agents', 'wallets', 'research', 'integrations', 'observability', 'support', 'content', 'operations', 'identity', 'extensions', 'extensions'
AS $function$
BEGIN
  -- The synthetic community owner publishes via wallet signature and keeps the
  -- manual verification gate. Every other owner is a portal/dashboard provider
  -- who passed Monerium KYB before they could reach the "create API" screen.
  IF NEW.owner_id IS DISTINCT FROM '00000000-0000-0000-0000-000000000001'::uuid THEN
    NEW.is_verified := true;
    IF NEW.verified_at IS NULL THEN
      NEW.verified_at := now();
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.default_endpoint_network_token_from_api()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'gateway_v2', 'kyb', 'providers', 'catalog', 'actions', 'billing', 'agents', 'wallets', 'research', 'integrations', 'observability', 'support', 'content', 'operations', 'identity', 'extensions', 'extensions'
AS $function$
declare
  v_network text;
  v_token_id uuid;
begin
  if new.payment_required is distinct from true or new.network_token_id is not null then
    return new;
  end if;

  select payout_network into v_network from apis where id = new.api_id;
  if v_network is null or v_network = 'base' then
    return new; -- gateway default already IS base USDC
  end if;

  select nt.id into v_token_id
  from network_tokens nt
  join networks n on n.id = nt.network_id
  join tokens t on t.id = nt.token_id
  where n.name = v_network
    and n.is_testnet = false and n.is_active = true
    and t.symbol = 'USDC' and nt.is_active = true
  limit 1;

  if v_token_id is not null then
    new.network_token_id := v_token_id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_base_mainnet_endpoint_network_token()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'gateway_v2', 'kyb', 'providers', 'catalog', 'actions', 'billing', 'agents', 'wallets', 'research', 'integrations', 'observability', 'support', 'content', 'operations', 'identity', 'extensions', 'extensions'
AS $function$
begin
  if new.payment_required is distinct from true then
    new.network_token_id := null;
    return new;
  end if;

  if new.network_token_id is null then
    return new;
  end if;

  if not exists (
    select 1
    from network_tokens nt
    join networks n on n.id = nt.network_id
    join tokens t on t.id = nt.token_id
    where nt.id = new.network_token_id
      and nt.is_active = true
      and n.is_active = true
      and n.name in ('base', 'polygon', 'arbitrum')
      and n.is_testnet = false
      and t.symbol = 'USDC'
  ) then
    raise exception 'api_endpoints.network_token_id must reference an active mainnet USDC token on base/polygon/arbitrum'
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_api_review_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'gateway_v2', 'kyb', 'providers', 'catalog', 'actions', 'billing', 'agents', 'wallets', 'research', 'integrations', 'observability', 'support', 'content', 'operations', 'identity', 'extensions'
AS $function$
declare
  v_event text;
  v_id uuid;
  v_token uuid;
begin
  if new.status = 'pending' and tg_op = 'INSERT' then
    v_event := 'pending';
  elsif tg_op = 'UPDATE'
        and new.status = 'pending'
        and old.status is distinct from 'pending' then
    v_event := 'pending';
  elsif tg_op = 'UPDATE'
        and old.status = 'pending'
        and new.status = 'active'
        and new.reviewed_by is not null then
    v_event := 'approved';
  elsif tg_op = 'UPDATE'
        and old.status = 'pending'
        and new.status = 'inactive'
        and new.reviewed_by is not null then
    v_event := 'rejected';
  else
    return new;
  end if;

  insert into operations.api_review_email_outbox(event, api_id, owner_id, api_name, api_slug)
  values (v_event, new.id, new.owner_id, coalesce(new.name, new.slug), new.slug)
  returning id, delivery_token into v_id, v_token;

  perform public.dispatch_api_review_email(v_id, v_token);
  return new;
exception when others then
  -- Notifications must never break the API lifecycle transaction.
  raise warning 'Could not enqueue API review email for %: %', new.id, sqlerrm;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_api_published()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_pat text;
begin
  -- Only rows becoming publicly active. status='active' is what the public
  -- catalog + gateway routing key off (admin_review_api sets it on approve).
  if new.status is distinct from 'active' then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.status = 'active' then
    return new; -- already active; not a publish transition
  end if;
  -- Gateway/Bazaar list standalone APIs only — never Connect merchandise.
  if new.listing_type is distinct from 'api' then
    return new;
  end if;

  begin
    select decrypted_secret into v_pat
      from vault.decrypted_secrets
     where name = 'github_dispatch_pat'
     limit 1;
  exception when others then
    v_pat := null; -- vault unreadable — treat as unconfigured
  end;

  if v_pat is null or length(trim(v_pat)) = 0 then
    raise notice 'api-published dispatch skipped for %: no github_dispatch_pat in vault (daily cron will pick it up)', new.slug;
    return new;
  end if;

  -- Async queue insert; the pg_net worker performs the HTTP call after commit.
  perform net.http_post(
    url     := 'https://api.github.com/repos/obcraft/apiosk-1-rust-gatway/dispatches',
    body    := jsonb_build_object(
                 'event_type', 'api-published',
                 'client_payload', jsonb_build_object(
                   'slug', new.slug,
                   'api_id', new.id,
                   'published_at', now()
                 )
               ),
    headers := jsonb_build_object(
                 'Authorization', 'Bearer ' || v_pat,
                 'Accept', 'application/vnd.github+json',
                 'X-GitHub-Api-Version', '2022-11-28',
                 'Content-Type', 'application/json',
                 'User-Agent', 'apiosk-publish-trigger'
               ),
    timeout_milliseconds := 5000
  );

  raise notice 'api-published dispatch queued for % (%)', new.slug, new.id;
  return new;
exception when others then
  -- Discovery plumbing must never break a publish/approval.
  raise warning 'api-published dispatch failed for %: %', new.slug, sqlerrm;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.require_payout_wallet_to_publish()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'gateway_v2', 'kyb', 'providers', 'catalog', 'actions', 'billing', 'agents', 'wallets', 'research', 'integrations', 'observability', 'support', 'content', 'operations', 'identity', 'extensions'
AS $function$
declare
  addr text := lower(btrim(coalesce(new.wallet_address, '')));
  entering boolean := tg_op = 'INSERT'
                      or old.status is distinct from new.status
                      or old.wallet_address is distinct from new.wallet_address
                      or old.settlement_mode is distinct from new.settlement_mode;
begin
  if new.status not in ('pending', 'active') or not entering then
    return new;
  end if;

  -- Only external provider settlement requires a payout wallet.
  if new.settlement_mode = 'provider_payout' then
    if addr = ''
       or addr = '0x0000000000000000000000000000000000000000'
       or addr !~ '^0x[0-9a-f]{40}$'
    then
      raise exception 'A payout wallet is required for provider_payout listings'
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$function$
